CREATE COLUMN TABLE "TEST_AP"."ATT2" ("Father" NVARCHAR(50) NOT NULL , "StageId" INTEGER CS_INT NOT NULL , "SeqNum" INTEGER CS_INT NOT NULL , "StgEntry" INTEGER CS_INT, "Name" NVARCHAR(100), "LogInstanc" INTEGER CS_INT DEFAULT 0 NOT NULL , "WaitDays" DECIMAL(21,6) CS_FIXED DEFAULT 0, PRIMARY KEY ("Father", "StageId", "LogInstanc")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "ATT2_SEQUENCE" ON "TEST_AP"."ATT2" ( "Father" ASC, "SeqNum" ASC, "LogInstanc" ASC )